import { JSON_API } from '../common/jsonapi.js';

const errorResponse = (description: string) => ({
  description,
  content: { [JSON_API]: { schema: { $ref: '#/components/schemas/ErrorDocument' } } },
});

const jsonApiBody = (schema: string) => ({
  required: true,
  content: { [JSON_API]: { schema: { $ref: `#/components/schemas/${schema}` } } },
});

const pageParameters = [
  { $ref: '#/components/parameters/PageNumber' },
  { $ref: '#/components/parameters/PageSize' },
];

const customerHeader = { $ref: '#/components/parameters/CustomerId' };

const unauthorized = errorResponse('Missing, unknown or malformed Customer-Id header');

function listOperation(summary: string, parameters: unknown[], itemSchema: string, listSchema: string) {
  return {
    summary,
    parameters,
    responses: {
      '200': {
        description: 'A page of resources',
        content: { [JSON_API]: { schema: { $ref: `#/components/schemas/${listSchema}` } } },
      },
      '400': errorResponse('Invalid query parameter'),
    },
    'x-item-schema': itemSchema,
  };
}

const bookSortEnum = ['priceCents', 'title', 'publishedAt', '-priceCents', '-title', '-publishedAt'];

const bookFilters = [
  { name: 'filter[title]', in: 'query', schema: { type: 'string' }, description: 'Title contains the text, case-insensitive' },
  { name: 'filter[author]', in: 'query', schema: { type: 'string' }, description: 'Author name, exact' },
  { name: 'filter[minPrice]', in: 'query', schema: { type: 'integer' }, description: 'Price in cents, lower bound included' },
  { name: 'filter[maxPrice]', in: 'query', schema: { type: 'integer' }, description: 'Price in cents, upper bound included' },
  { name: 'filter[publishedAfter]', in: 'query', schema: { type: 'string', format: 'date' }, description: 'Published on or after this date' },
  { name: 'filter[publishedBefore]', in: 'query', schema: { type: 'string', format: 'date' }, description: 'Published on or before this date' },
  { name: 'filter[inStock]', in: 'query', schema: { type: 'boolean' }, description: 'true: stock above 0; false: stock 0' },
];

export const OPENAPI_DOCUMENT = {
  openapi: '3.0.3',
  info: {
    title: 'Bookshop API',
    version: '1.0.0',
    description: 'JSON:API 1.1 bookshop. Responses use application/vnd.api+json.',
  },
  paths: {
    '/authors': {
      get: listOperation(
        'List authors',
        [
          ...pageParameters,
          {
            name: 'sort',
            in: 'query',
            schema: { type: 'string', example: '-publishedBooks,name' },
            description: 'Comma separated fields among name and publishedBooks; prefix - for descending',
          },
          {
            name: 'include',
            in: 'query',
            schema: { type: 'string', enum: ['books'] },
            description: 'Adds the published books of the authors to included',
          },
        ],
        'Author',
        'AuthorList',
      ),
    },
    '/authors/{id}': {
      get: {
        summary: 'Get an author',
        parameters: [
          { $ref: '#/components/parameters/Id' },
          {
            name: 'include',
            in: 'query',
            schema: { type: 'string', enum: ['books'] },
            description: 'Adds the published books to included',
          },
        ],
        responses: {
          '200': {
            description: 'The author',
            content: { [JSON_API]: { schema: { $ref: '#/components/schemas/AuthorDocument' } } },
          },
          '404': errorResponse('Unknown author'),
        },
      },
    },
    '/books': {
      get: listOperation(
        'List published books',
        [
          ...pageParameters,
          ...bookFilters,
          {
            name: 'sort',
            in: 'query',
            schema: { type: 'string' },
            description: `Comma separated fields among priceCents, title and publishedAt; prefix - for descending. Allowed values include: ${bookSortEnum.join(', ')}`,
          },
          {
            name: 'include',
            in: 'query',
            schema: { type: 'string', enum: ['author'] },
            description: 'Adds the authors to included',
          },
        ],
