const B = 'http://localhost:8089';
let fails = 0;
const ok = (cond, label, extra) => { if (!cond) fails++; console.log(`${cond ? 'PASS' : 'FAIL'} ${label}${cond ? '' : ' :: ' + JSON.stringify(extra)}`); };
async function call(method, path, { headers = {}, body, raw } = {}) {
  const init = { method, headers: { Accept: 'application/vnd.api+json', ...headers } };
  if (raw !== undefined) init.body = raw;
  else if (body !== undefined) { init.body = JSON.stringify(body); init.headers['Content-Type'] = 'application/vnd.api+json'; }
  const r = await fetch(B + path, init);
  const text = await r.text();
  let json; try { json = JSON.parse(text); } catch { json = undefined; }
  return { status: r.status, type: r.headers.get('content-type'), loc: r.headers.get('location'), text, json };
}
const cust = { 'Customer-Id': '1' };

// books
let r = await call('GET', '/books');
ok(r.status === 200 && r.json.data.length === 10 && r.json.meta.total === 14, 'books default page 10, total published 14', [r.status, r.json?.meta]);
ok(r.json.links.prev === null && r.json.links.next.includes('page[number]=2'), 'links first page', r.json.links);
